tools.schemaJson:
{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Path to the file to read (relative or absolute). May end with a trailing selector such as :50-100 or :raw, address an archive member (archive.zip:inner/file), or address a SQLite database (data.db:table?limit=20)"
    },
    "offset": {
      "type": "integer",
      "description": "Line number to start reading from (1-indexed)"
    },
    "limit": {
      "type": "integer",
      "description": "Maximum number of lines to read"
    },
    "hashline": {
      "type": "boolean",
      "description": "Prefix each line with its line number and prepend a [path#TAG] content-hash header for anchoring hashline edit patches (default: false)"
    }
  },
  "required": [
    "path"
  ]
}

{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Path to the file to write (relative or absolute)"
    },
    "content": {
      "type": "string",
      "description": "Content to write to the file"
    }
  },
  "required": [
    "path",
    "content"
  ]
}

{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Path to the file to edit (relative or absolute). Required for exact-match mode; optional in hashline mode (the patch header carries its own [path#TAG])."
    },
    "oldText": {
      "type": "string",
      "description": "Exact-match mode: exact text to replace. Must occur exactly once in the file."
    },
    "newText": {
      "type": "string",
      "description": "Exact-match mode: replacement text (may be empty to delete oldText)."
    },
    "patch": {
      "type": "string",
      "description": "Hashline mode: a hashline patch — [path#TAG] section header(s) followed by SWAP/DEL/INS ops anchored on line numbers from a hashline-mode read."
    }
  }
}

{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Directory to list (default: current directory)"
    },
    "limit": {
      "type": "integer",
      "description": "Maximum number of entries to return (default: 500)"
    }
  }
}

{
  "type": "object",
  "properties": {
    "command": {
      "type": "string",
      "description": "The bash command to execute"
    },
    "timeout": {
      "type": "number",
      "description": "Timeout in seconds (optional, no default timeout)"
    },
    "background": {
      "type": "boolean",
      "description": "Run detached and return the job id immediately (optional, default false). Use for long-running commands."
    },
    "stdin": {
      "type": "string",
      "description": "Optional text written to the command's stdin right after start (a password/passphrase the USER supplied via the ask tool, or \"y\\n\"). Use when the command prompts for input, e.g. ssh-add or sudo. Never invent secrets — ask first."
    }
  },
  "required": [
    "command"
  ]
}

{
  "type": "object",
  "properties": {
    "action": {
      "type": "string",
      "enum": [
        "status",
        "output",
        "stop"
      ],
      "description": "What to do with the job(s)"
    },
    "id": {
      "type": "string",
      "description": "The job id (e.g. sh-1); required for output/stop"
    },
    "lines": {
      "type": "number",
      "description": "Log tail size for output (default 50)"
    },
    "all": {
      "type": "boolean",
      "description": "status without id: list every exited job too"
    }
  },
  "required": [
    "action"
  ]
}

{
  "type": "object",
  "properties": {
    "op": {
      "type": "string",
      "enum": [
        "diagnostics",
        "definition",
        "references",
        "rename"
      ],
      "description": "The language-server operation to run"
    },
    "path": {
      "type": "string",
      "description": "File to inspect (relative or absolute). For rename, the file containing the symbol"
    },
    "line": {
      "type": "integer",
      "description": "1-indexed line of the symbol (default 1); used by definition/references/rename"
    },
    "character": {
      "type": "integer",
      "description": "1-indexed character (column) of the symbol (default 1); used by definition/references/rename"
    },
    "newName": {
      "type": "string",
      "description": "The new identifier (required for rename)"
    }
  },
  "required": [
    "op",
    "path"
  ]
}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
      "description": "The search query"
    },
    "count": {
      "type": "integer",
      "description": "Maximum number of results to return (default: 10, max: 20)"
    },
    "site": {
      "type": "string",
      "description": "Restrict results to a single domain, e.g. 'pub.dev' (appended as a site: filter)"
    }
  },
  "required": [
    "query"
  ]
}

{
  "type": "object",
  "properties": {
    "url": {
      "type": "string",
      "description": "The absolute http(s) URL to fetch"
    }
  },
  "required": [
    "url"
  ]
}

{
  "type": "object",
  "properties": {
    "op": {
      "type": "string",
      "enum": [
        "check",
        "path",
        "get",
        "set"
      ],
      "description": "The config operation to run"
    },
    "key": {
      "type": "string",
      "description": "Dotted config key for get/set (memory.projectPath, tools.web_search, provider, ...)"
    },
    "value": {
      "type": "string",
      "description": "The new value for set, rendered as a yaml scalar: true/false verbatim, numbers verbatim, lists/maps as compact JSON, strings plain or quoted"
    },
    "scope": {
      "type": "string",
      "enum": [
        "global",
        "project"
      ],
      "description": "Write scope for set. Default resolves by key: memory/cube/tools -> the project file (created minimal when absent), everything else -> the user file"
    }
  },
  "required": [
    "op"
  ]
}

{
  "type": "object",
  "properties": {
    "text": {
      "type": "string",
      "description": "The memory content — a concise, self-contained fact."
    },
    "tags": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Optional tags for categorization and retrieval."
    },
    "scope": {
      "type": "string",
      "enum": [
        "project",
        "user"
      ],
      "description": "Where to store: project (default) or user (global)."
    }
  },
  "required": [
    "text"
  ]
}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
      "description": "What to search for — a question, topic, or keyword."
    }
  },
  "required": [
    "query"
  ]
}

{
  "type": "object",
  "properties": {
    "limit": {
      "type": "integer",
      "description": "Max entries to return (default 20)."
    }
  }
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The memory entry id (from memory_list/search)."
    },
    "scope": {
      "type": "string",
      "enum": [
        "project",
        "user"
      ],
      "description": "Restrict deletion to one scope; default scans both."
    }
  },
  "required": [
    "id"
  ]
}

{
  "type": "object",
  "properties": {
    "text": {
      "type": "string",
      "description": "The message to deliver when the timer fires."
    },
    "delay": {
      "type": "string",
      "description": "How long to wait: 90s / 25m / 2h / 1d (combinable, e.g. 1h30m)."
    },
    "to": {
      "type": "string",
      "description": "Recipient mailbox id; defaults to your own mailbox."
    }
  },
  "required": [
    "text",
    "delay"
  ]
}

{
  "type": "object",
  "properties": {
    "questions": {
      "type": "array",
      "description": "Questions to ask the user (at least one)",
      "items": {
        "type": "object",
        "properties": {
          "question": {
            "type": "string",
            "description": "Question text shown to the user"
          },
          "options": {
            "type": "array",
            "description": "Picker options (2-5 concise, distinct options); omit for a free-form answer",
            "items": {
              "type": "object",
              "properties": {
                "label": {
                  "type": "string",
                  "description": "Short display label"
                },
                "description": {
                  "type": "string",
                  "description": "Optional explanatory text shown with the label"
                }
              },
              "required": [
                "label"
              ]
            }
          },
          "multiSelect": {
            "type": "boolean",
            "description": "Allow multiple selections (default: false)"
          },
          "recommended": {
            "type": [
              "integer",
              "string"
            ],
            "description": "Recommended option: 0-based index or exact label; rendered as a \"Recommended\" badge"
          }
        },
        "required": [
          "question"
        ]
      }
    }
  },
  "required": [
    "questions"
  ]
}

{
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "description": "Env var name to save the credential under (UPPER_SNAKE, e.g. GITHUB_TOKEN); prefilled in the user prompt"
    },
    "reason": {
      "type": "string",
      "description": "Why the credential is needed; shown to the user in the prompt"
    }
  },
  "required": [
    "name",
    "reason"
  ]
}

{
  "type": "object",
  "properties": {
    "prompt": {
      "type": "string",
      "description": "text prompt describing the image to generate"
    },
    "size": {
      "type": "string",
      "description": "image size, e.g. 1024x1024"
    },
    "quality": {
      "type": "string",
      "description": "image quality, e.g. standard or high"
    }
  },
  "required": [
    "prompt"
  ]
}

{
  "type": "object",
  "properties": {
    "prompt": {
      "type": "string",
      "description": "text prompt describing the video to generate"
    },
    "size": {
      "type": "string",
      "description": "video size, e.g. 1920x1080"
    },
    "quality": {
      "type": "string",
      "description": "video quality, e.g. standard or high"
    }
  },
  "required": [
    "prompt"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "Optional: a specific subagent id. Omit to list all."
    }
  }
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The subagent id to observe."
    },
    "tail": {
      "type": "integer",
      "description": "Number of recent messages to read (default 10)."
    }
  },
  "required": [
    "id"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The subagent id to message."
    },
    "message": {
      "type": "string",
      "description": "The follow-up instruction or question."
    }
  },
  "required": [
    "id",
    "message"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The failed subagent id."
    },
    "message": {
      "type": "string",
      "description": "Optional resume instruction. Default: continue the original task from where the child stopped."
    }
  },
  "required": [
    "id"
  ]
}

{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "The background job id to abort."
    }
  },
  "required": [
    "id"
  ]
}

{
  "type": "object",
  "properties": {
    "message": {
      "type": "string",
      "description": "The answer/deliverable for the parent."
    }
  },
  "required": [
    "message"
  ]
}

{
  "type": "object",
  "properties": {
    "to": {
      "type": "string",
      "description": "The sibling subagent id, \"main\", an absolute mailbox \"<sessionId>/main\", a session name from agent_directory, or \"name@machine\" for a cross-machine peer (A2A gateway)."
    },
    "message": {
      "type": "string",
      "description": "The message body for the sibling."
    },
    "wake": {
      "type": "boolean",
      "description": "When the cross-session target is asleep (no live watcher — it would not read the message until started), launch a detached headless run of its session to process the inbox now. Default: true. The run appends to the same session JSONL, so a later interactive start resumes it."
    }
  },
  "required": [
    "to",
    "message"
  ]
}

{
  "type": "object",
  "properties": {
    "all": {
      "type": "boolean",
      "description": "Include stale mailboxes (no recent activity, nothing pending). Default: false."
    }
  }
}

{
  "type": "object",
  "properties": {
    "context": {
      "type": "string",
      "description": "Shared background (project state, constraints, contracts) rendered into every spawned subagent's system prompt"
    },
    "tasks": {
      "type": "array",
      "description": "One subagent per item",
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Stable id base ([A-Za-z0-9_-]); uniquified per session"
          },
          "agent": {
            "type": "string",
            "description": "Agent type for this item (see the tool description); omit for the general-purpose worker"
          },
          "task": {
            "type": "string",
            "description": "Complete, self-contained instructions for the subagent"
          },
          "outputSchema": {
            "description": "JSON Schema the subagent's final output must satisfy; invalid output gets one fix retry, then the item fails"
          }
        },
        "required": [
          "task"
        ]
      }
    },
    "background": {
      "type": "boolean",
      "description": "Run items as background jobs and return job ids immediately (default: host configuration)"
    }
  },
  "required": [
    "context",
    "tasks"
  ]
}

{
  "type": "object",
  "properties": {
    "goal": {
      "type": "string",
      "description": "Investigation goal for this checkpoint"
    }
  }
}

{
  "type": "object",
  "properties": {
    "report": {
      "type": "string",
      "description": "Investigation findings retained after the rewind"
    }
  },
  "required": [
    "report"
  ]
}

{
  "type": "object",
  "properties": {
    "target": {
      "type": "string",
      "description": "Numeric id or range from a context marker, e.g. \"5\" or \"2-6\". Omit to list the hidden-segment index."
    },
    "action": {
      "type": "string",
      "description": "Tier 2 segment management (issue #1379). With a target: \"hide\" folds a dead-weight segment into its expandable marker right now, without waiting for pressure; \"pin\" shields a segment from every hide/compact path; \"unpin\" releases it. Omit to expand the target."
    },
    "query": {
      "type": "string",
      "description": "Search the hidden segments (preview and full content) when you know WHAT you need but not the id. Free — no budget."
    },
    "page": {
      "type": "integer",
      "description": "1-based page for giant segments (default 1)",
      "minimum": 1
    }
  },
  "required": []
}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
      "description": "The phrase to search for (keyword, or a regular expression with regex: true). Required in search mode."
    },
    "scope": {
      "type": "string",
      "enum": [
        "branch",
        "tree"
      ],
      "description": "branch (default) searches the active branch only; tree spans forks and abandoned branches too."
    },
    "mode": {
      "type": "string",
      "enum": [
        "search",
        "map"
      ],
      "description": "search (default) finds records; map reports the archive structure (counts, hidden totals, checkpoint tree)."
    },
    "kinds": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Only these record types (message, compaction, compact_checkpoint, custom, …). Empty keeps every kind."
    },
    "before": {
      "type": "string",
      "description": "Only records older than this ISO-8601 instant."
    },
    "after": {
      "type": "string",
      "description": "Only records newer than this ISO-8601 instant."
    },
    "regex": {
      "type": "boolean",
      "description": "Match query as a case-insensitive regular expression (default: literal keyword)."
    },
    "maxHits": {
      "type": "integer",
      "description": "Cap on returned pointers (default 40, max 200). A capped scan returns a continuation token."
    },
    "continuation": {
      "type": "integer",
      "description": "The token a previous capped call returned — resumes the scan after the records already examined."
    }
  }
}

